def magic_square_test(square):
    if not square or not square[0]:
        return False

    n = len(square)

    # Check if it's a square matrix
    for row in square:
        if len(row) != n:
            return False

    # Collect all numbers
    all_numbers = []
    for row in square:
        for num in row:
            all_numbers.append(num)

    # Check if numbers are 1 to n^2
    expected = set(range(1, n * n + 1))
    actual = set(all_numbers)
    if actual != expected:
        return False

    # Calculate the magic constant
    magic_sum = n * (n * n + 1) // 2

    # Check rows
    for row in square:
        if sum(row) != magic_sum:
            return False

    # Check columns
    for col in range(n):
        col_sum = sum(square[row][col] for row in range(n))
        if col_sum != magic_sum:
            return False

    # Check main diagonal
    main_diag_sum = sum(square[i][i] for i in range(n))
    if main_diag_sum != magic_sum:
        return False

    # Check anti-diagonal
    anti_diag_sum = sum(square[i][n - 1 - i] for i in range(n))
    if anti_diag_sum != magic_sum:
        return False

    return True
