def max_path_sum(triangle, n, m):
    """
    Find the maximum total path sum in the given triangle.

    Args:
        triangle: A 2D list representing the triangle, where triangle[i][j] is the value at row i, column j.
                  The triangle is represented as a full matrix with 0s for unused positions.
        n: Number of rows in the triangle.
        m: Number of columns in the triangle (should be equal to n for a proper triangle).

    Returns:
        The maximum path sum from top to bottom.
    """
    if n == 0:
        return 0

    # Create a DP table with the same dimensions as the triangle
    dp = [[0] * m for _ in range(n)]

    # Initialize the top of the triangle
    dp[0][0] = triangle[0][0]

    # Fill the DP table
    for i in range(1, n):
        for j in range(m):
            # If the position is 0 in the original triangle, it's not part of the triangle
            if triangle[i][j] == 0 and i > 0:
                # Check if this position could be reached (i.e., j <= i)
                if j > i:
                    dp[i][j] = 0
                    continue
                # If j == 0, can only come from dp[i-1][0]
                if j == 0:
                    dp[i][j] = dp[i-1][j] + triangle[i][j]
                elif j == i:
                    # Can only come from dp[i-1][j-1]
                    dp[i][j] = dp[i-1][j-1] + triangle[i][j]
                else:
                    # Can come from dp[i-1][j-1] or dp[i-1][j]
                    dp[i][j] = max(dp[i-1][j-1], dp[i-1][j]) + triangle[i][j]
            else:
                if j == 0:
                    dp[i][j] = dp[i-1][j] + triangle[i][j]
                elif j == i:
                    dp[i][j] = dp[i-1][j-1] + triangle[i][j]
                else:
                    dp[i][j] = max(dp[i-1][j-1], dp[i-1][j]) + triangle[i][j]

    # The answer is the maximum value in the last row
    return max(dp[n-1])
