def find_Min(arr, low, high):
    # Base case: if the array is not rotated (first element is less than last)
    if arr[low] <= arr[high]:
        return arr[low]

    # Binary search
    while low <= high:
        mid = (low + high) // 2

        # Check if mid is the minimum element
        # It is the minimum if it's smaller than both its neighbors
        if mid > 0 and arr[mid] < arr[mid - 1]:
            return arr[mid]
        if mid < high and arr[mid] > arr[mid + 1]:
            return arr[mid + 1]

        # Decide which half to search
        if arr[mid] >= arr[low]:
            # Minimum is in the right half
            low = mid + 1
        else:
            # Minimum is in the left half
            high = mid - 1

    return arr[low]
```

