def newman_prime(n):
    """
    Find the nth Newman-Shanks-Williams prime number.

    The Newman-Shanks-Williams sequence is defined as:
    NSW(0) = 1
    NSW(1) = 1
    NSW(n) = 2 * NSW(n-1) + NSW(n-2) for n >= 2

    The nth NSW prime is the nth prime number in the sequence of NSW numbers.
    """
    def nsw_sequence(k):
        """Compute the k-th term of the NSW sequence."""
        if k == 0 or k == 1:
            return 1
        a, b = 1, 1
        for i in range(2, k + 1):
            a, b = b, 2 * b + a
        return b

    def is_prime(num):
        """Check if a number is prime."""
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(num**0.5) + 1, 2):
            if num % i == 0:
                return False
        return True

    # Generate NSW numbers and find the nth one that is prime
    count = 0
    k = 0
    while True:
        nsw_val = nsw_sequence(k)
        if is_prime(nsw_val):
            count += 1
            if count == n:
                return nsw_val
        k += 1
