def set_left_most_unset_bit(n: int) -> int:
    if n < 0:
        return n

    # Find the position of the leftmost unset bit
    # We need to find the highest bit position that is 0
    # First, find the total number of bits needed to represent n
    if n == 0:
        return 1  # Leftmost unset bit of 0 (which is 0 in binary) is at position 0

    # Find the most significant bit position
    msb_pos = n.bit_length() - 1

    # Check from the most significant bit down to 0
    # The leftmost unset bit is the highest position where bit is 0
    for i in range(msb_pos, -1, -1):
        if not (n & (1 << i)):
            # Set this bit
            return n | (1 << i)

    # If all bits up to msb_pos are set, we need to set the next bit
    return n | (1 << (msb_pos + 1))
