def find_Divisor(start, end):
    """
    Find the maximum occurring divisor in the interval [start, end].

    The "maximum occurring divisor" refers to the divisor that divides the most numbers
    in the given interval. If there's a tie, return the largest such divisor.

    Args:
        start: Start of the interval (inclusive)
        end: End of the interval (inclusive)

    Returns:
        The divisor that occurs most frequently in the interval
    """
    if start > end:
        return None

    # For each number in the interval, find all its divisors
    # Count how many times each divisor appears
    divisor_count = {}

    for num in range(start, end + 1):
        # Find all divisors of num
        for d in range(1, int(num**0.5) + 1):
            if num % d == 0:
                divisor_count[d] = divisor_count.get(d, 0) + 1
                if d != num // d:
                    divisor_count[num // d] = divisor_count.get(num // d, 0) + 1

    if not divisor_count:
        return None

    # Find the divisor with the maximum count
    # If tie, return the largest divisor
    max_count = max(divisor_count.values())
    candidates = [d for d, count in divisor_count.items() if count == max_count]

    return max(candidates)
```

