def first_Factorial_Divisible_Number(x):
    if x <= 1:
        return 1

    # We need to find the smallest n such that n! is divisible by x
    # Factorize x into prime factors
    # For each prime factor p with exponent e in x,
    # we need n! to have at least e factors of p
    # The number of factors of p in n! is given by Legendre's formula

    def legendre(n, p):
        count = 0
        while n > 0:
            count += n // p
            n //= p
        return count

    def prime_factorization(n):
        factors = {}
        d = 2
        while d * d <= n:
            while n % d == 0:
                factors[d] = factors.get(d, 0) + 1
                n //= d
            d += 1
        if n > 1:
            factors[n] = factors.get(n, 0) + 1
        return factors

    factors = prime_factorization(x)

    # For each prime factor, find the smallest n such that legendre(n, p) >= exponent
    # Then take the maximum of all such n

    def min_n_for_prime(p, exponent):
        # Binary search for the smallest n such that legendre(n, p) >= exponent
        lo, hi = 1, exponent * p  # upper bound: n! has at least n/p factors of p, so n >= exponent * p roughly
        while lo < hi:
            mid = (lo + hi) // 2
            if legendre(mid, p) >= exponent:
                hi = mid
            else:
                lo = mid + 1
        return lo

    result = 1
    for p, exponent in factors.items():
        n_needed = min_n_for_prime(p, exponent)
        result = max(result, n_needed)

    return result
