class Solution:
    def countAlternatingSubarrays(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 0:
            return 0

        total = 0
        # For each position, track the length of the alternating subarray ending at that position
        # If nums[i] != nums[i-1], then we can extend the alternating subarray
        # Otherwise, the alternating subarray ending at i has length 1 (just nums[i] itself)

        # dp[i] = length of longest alternating subarray ending at index i
        # The number of alternating subarrays ending at i is dp[i]
        # Because if the longest alternating subarray ending at i has length L,
        # then all subarrays ending at i with length 1, 2, ..., L are also alternating

        dp = 0
        for i in range(n):
            if i == 0:
                dp = 1
            else:
                if nums[i] != nums[i - 1]:
                    dp += 1
                else:
                    dp = 1
            total += dp

        return total
