class Solution:
    def maximumLength(self, nums: List[int], k: int) -> int:
        n = len(nums)
        if n == 0:
            return 0

        # dp[i][j] = maximum length of a good subsequence ending at index i with exactly j changes
        # But we need to track the last value to know if adding a new element causes a change.
        # Alternative: dp[i][j] = max length of good subsequence using elements from nums[0..i] ending with nums[i], with j changes.
        # To compute dp[i][j], we look at all prev < i:
        #   if nums[prev] == nums[i]: dp[i][j] = max(dp[i][j], dp[prev][j])
        #   if nums[prev] != nums[i]: dp[i][j] = max(dp[i][j], dp[prev][j-1]) for j >= 1
        # Base case: dp[i][0] = 1 for all i (subsequence of just nums[i] has 0 changes)

        # Initialize dp table
        # dp[i][j] = maximum length of good subsequence ending at index i with j changes
        dp = [[0] * (k + 1) for _ in range(n)]

        for i in range(n):
            dp[i][0] = 1  # Subsequence containing only nums[i]
            for j in range(1, k + 1):
                dp[i][j] = 1  # At minimum, we can have just nums[i]

        for i in range(n):
            for prev in range(i):
                for j in range(k + 1):
                    if nums[prev] == nums[i]:
                        # No additional change
                        if dp[prev][j] + 1 > dp[i][j]:
                            dp[i][j] = dp[prev][j] + 1
                    else:
                        # Additional change, need j >= 1
                        if j >= 1 and dp[prev][j - 1] + 1 > dp[i][j]:
                            dp[i][j] = dp[prev][j - 1] + 1

        # The answer is the maximum value in the entire dp table
        result = 0
        for i in range(n):
            for j in range(k + 1):
                if dp[i][j] > result:
                    result = dp[i][j]

        return result
