        for i in range(1, n):
            word = words[i]
            w_len = len(word)
            w_first = ord(word[0]) - ord('a')
            w_last = ord(word[-1]) - ord('a')

            new_dp = [[INF] * 26 for _ in range(26)]

            for fc in range(26):
                for lc in range(26):
                    if dp[fc][lc] == INF:
                        continue

                    current_len = dp[fc][lc]

                    # Option 1: join(current_string, word)
                    # current_string ends with lc, word starts with w_first
                    # If lc == w_first, we save 1 character
                    if lc == w_first:
                        new_len = current_len + w_len - 1
                    else:
                        new_len = current_len + w_len
                    # New first char is fc, new last char is w_last
                    if new_len < new_dp[fc][w_last]:
                        new_dp[fc][w_last] = new_len

                    # Option 2: join(word, current_string)
                    # word ends with w_last, current_string starts with fc
                    # If w_last == fc, we save 1 character
                    if w_last == fc:
                        new_len2 = current_len + w_len - 1
                    else:
                        new_len2 = current_len + w_len
                    # New first char is w_first, new last char is lc
                    if new_len2 < new_dp[w_first][lc]:
                        new_dp[w_first][lc] = new_len2

            dp = new_dp

        # Find the minimum value in dp
        result = INF
        for fc in range(26):
            for lc in range(26):
                if dp[fc][lc] < result:
                    result = dp[fc][lc]

        return result
