class Solution:
    def maxScore(self, nums: list[int], x: int) -> int:
        n = len(nums)
        # dp[0] = max score ending at an even number
        # dp[1] = max score ending at an odd number
        # Initialize with -infinity
        dp = [-float('inf'), -float('inf')]

        # Process the first element
        if nums[0] % 2 == 0:
            dp[0] = nums[0]
        else:
            dp[1] = nums[0]

        for i in range(1, n):
            val = nums[i]
            is_even = val % 2 == 0

            new_dp = [-float('inf'), -float('inf')]

            if is_even:
                # Current is even
                # From previous even: no penalty
                if dp[0] != -float('inf'):
                    new_dp[0] = max(new_dp[0], dp[0] + val)
                # From previous odd: penalty x
                if dp[1] != -float('inf'):
                    new_dp[0] = max(new_dp[0], dp[1] + val - x)
