                    new_dp[1] = max(new_dp[1], dp[1] + val)
                # From previous even: penalty x
                if dp[0] != -float('inf'):
                    new_dp[1] = max(new_dp[1], dp[0] + val - x)

            dp = new_dp

        return max(dp)
