class Solution:
    def hasIncreasingSubarrays(self, nums: List[int], k: int) -> bool:
        n = len(nums)

        # Precompute which starting positions have strictly increasing subarrays of length k
        # is_increasing[i] is True if nums[i..i+k-1] is strictly increasing
        is_increasing = [False] * (n - k + 1)

        for i in range(n - k + 1):
            # Check if nums[i..i+k-1] is strictly increasing
            valid = True
            for j in range(i, i + k - 1):
                if nums[j] >= nums[j + 1]:
                    valid = False
                    break
            is_increasing[i] = valid

        # Check if there exist two adjacent subarrays of length k that are both strictly increasing
        # That means we need is_increasing[a] and is_increasing[a + k] to both be True
        for a in range(n - 2 * k + 1):
            if is_increasing[a] and is_increasing[a + k]:
                return True

        return False
