    def count(self, num1: str, num2: str, min_sum: int, max_sum: int) -> int:
        MOD = 10**9 + 7

        def count_up_to(n: str, min_s: int, max_s: int) -> int:
            """Count numbers from 0 to n (inclusive) with digit sum between min_s and max_s."""
            if not n:
                return 0

            L = len(n)
            # dp[i][j][tight] = number of ways to fill positions i..L-1
            # where current digit sum is j, and tight indicates if we're still bounded by n
            # We'll use memoization

            memo = {}

            def dp(idx: int, current_sum: int, tight: bool) -> int:
                if current_sum > max_s:
                    return 0
                if idx == L:
                    return 1 if min_s <= current_sum <= max_s else 0

                state = (idx, current_sum, tight)
                if state in memo:
                    return memo[state]

                limit = int(n[idx]) if tight else 9
                result = 0
                for d in range(limit + 1):
                    new_tight = tight and (d == limit)
                    result = (result + dp(idx + 1, current_sum + d, new_tight)) % MOD

                memo[state] = result
                return result

            return dp(0, 0, True)

        # Count good numbers in [num1, num2] = count_up_to(num2) - count_up_to(num1) + (1 if num1 is good else 0)
