        # Actually, let's think: count_up_to(n) counts numbers from 0 to n with digit sum in [min_sum, max_sum].
        # Since min_sum >= 1, 0 (digit sum 0) is never counted. So count_up_to(n) effectively counts 1..n.

        def count_range(n: str) -> int:
            """Count numbers from 1 to n with digit sum in [min_sum, max_sum]."""
            return count_up_to(n, min_sum, max_sum)

        result = (count_range(num2) - count_range(num1) + MOD) % MOD
        # Check if num1 itself is good
        digit_sum_num1 = sum(int(c) for c in num1)
        if min_sum <= digit_sum_num1 <= max_sum:
            result = (result + 1) % MOD

        return result
