class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        if n == 0:
            return 0

        # Union-Find data structure
        parent = list(range(n))
        rank = [0] * n

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(x, y):
            rx, ry = find(x), find(y)
            if rx == ry:
                return
            if rank[rx] < rank[ry]:
                parent[rx] = ry
            elif rank[rx] > rank[ry]:
                parent[ry] = rx
            else:
                parent[ry] = rx
                rank[rx] += 1

        # Build graph edges based on intersect >= k
        for i in range(n):
            set_i = set(properties[i])
            for j in range(i + 1, n):
                set_j = set(properties[j])
                common = len(set_i & set_j)
                if common >= k:
                    union(i, j)

        # Count connected components
        components = set()
        for i in range(n):
            components.add(find(i))

        return len(components)
