    def shortestDistanceAfterQueries(self, n: int, queries: List[List[int]]) -> List[int]:
        import heapq

        # Adjacency list for the graph
        adj = [[] for _ in range(n)]

        # Initially, there is a unidirectional road from city i to city i + 1
        for i in range(n - 1):
            adj[i].append(i + 1)

        def bfs_shortest_path():
            # BFS from 0 to n-1
            dist = [-1] * n
            dist[0] = 0
            queue = [0]
            while queue:
                new_queue = []
                for u in queue:
                    if u == n - 1:
                        return dist[n - 1]
                    for v in adj[u]:
                        if dist[v] == -1:
                            dist[v] = dist[u] + 1
                            new_queue.append(v)
                queue = new_queue
            return dist[n - 1]

        answer = []
        for u, v in queries:
            adj[u].append(v)
            # Compute shortest path from 0 to n-1
            # Since n is small (up to 500), BFS is feasible
            dist = [-1] * n
            dist[0] = 0
            queue = [0]
