class Solution:
    def longestAlternatingSubarray(self, nums: List[int], threshold: int) -> int:
        n = len(nums)
        max_len = 0

        for l in range(n):
            # Condition 1: nums[l] must be even
            if nums[l] % 2 != 0:
                continue
            # Condition 3: nums[l] <= threshold
            if nums[l] > threshold:
                continue

            # Start building the subarray from l
            current_len = 1
            max_len = max(max_len, current_len)

            for r in range(l + 1, n):
                # Condition 3: nums[r] <= threshold
                if nums[r] > threshold:
                    break
                # Condition 2: nums[r-1] % 2 != nums[r] % 2
                if nums[r - 1] % 2 == nums[r] % 2:
                    break
                current_len += 1
                max_len = max(max_len, current_len)

        return max_len
