class Solution:
    def specialPerm(self, nums: List[int]) -> int:
        n = len(nums)
        MOD = 10**9 + 7

        # Precompute compatibility: can nums[i] and nums[j] be adjacent?
        # Two numbers can be adjacent if one divides the other
        compatible = [[False] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if i == j:
                    continue
                if nums[i] % nums[j] == 0 or nums[j] % nums[i] == 0:
                    compatible[i][j] = True

        # DP with bitmask
        # dp[mask][last] = number of ways to arrange the elements in mask, ending with element 'last'
        # mask is a bitmask where bit i is set if nums[i] is included
        full_mask = (1 << n) - 1

        # Initialize dp
        # For each single element, there's 1 way to have a permutation of just that element
        dp = [[0] * n for _ in range(1 << n)]
        for i in range(n):
            dp[1 << i][i] = 1

        # Iterate over all masks
        for mask in range(1, 1 << n):
            for last in range(n):
                if dp[mask][last] == 0:
                    continue
                if not (mask & (1 << last)):
                    continue
                # Try to add a new element 'next' that is not in mask
                for nxt in range(n):
                    if mask & (1 << nxt):
                        continue
                    if compatible[last][nxt]:
                        new_mask = mask | (1 << nxt)
                        dp[new_mask][nxt] = (dp[new_mask][nxt] + dp[mask][last]) % MOD

        # Sum up all dp[full_mask][last] for all last
        result = 0
        for last in range(n):
            result = (result + dp[full_mask][last]) % MOD

        return result
```

