class Solution:
    def countDays(self, days: int, meetings: List[List[int]]) -> int:
        if not meetings:
            return days

        # Sort meetings by start day
        meetings.sort()

        # Merge overlapping intervals
        merged = []
        for start, end in meetings:
            if merged and start <= merged[-1][1] + 1:
                # Overlapping or adjacent, merge them
                merged[-1] = (merged[-1][0], max(merged[-1][1], end))
            else:
                merged.append((start, end))

        # Calculate total days covered by meetings
        covered_days = 0
        for start, end in merged:
            # Clamp to the range [1, days]
            actual_start = max(start, 1)
            actual_end = min(end, days)
            if actual_start <= actual_end:
                covered_days += (actual_end - actual_start + 1)

        return days - covered_days
