class Solution:
    def punishmentNumber(self, n: int) -> int:
        def can_partition(s: str, target: int) -> bool:
            # Try all possible partitions of the string s
            # such that the sum of the parts equals target
            if not s:
                return target == 0

            # Try taking substrings from the beginning
            for i in range(1, len(s) + 1):
                part = int(s[:i])
                if part > target:
                    break
                if can_partition(s[i:], target - part):
                    return True
            return False

        total = 0
        for i in range(1, n + 1):
            square = i * i
            s = str(square)
            if can_partition(s, i):
                total += square
        return total
```
